      box-sizing: border-box
      transform: translate3d(0, 0, 0)
      z-index: 2000
      display: block
      position: absolute
      top: 0
      left: 0
      height: 100%
      width: 0
      background: var(--efu-theme)
      animation: android-loader 2s ease infinite
      background-size: 200%

@keyframes android-loader
